		rebuildGraphUpdateManager =
			new SwingUpdateManager(1000, 10000, () => refreshAndKeepPerspective());

		updateLocationUpdateManager =
			new SwingUpdateManager(250, 750, () => setPendingLocationFromUpdateManager());

